const mod = 998244353n;

function ggt(a, b) {
    if (a < b) return ggt(b, a);
    if (b === 0n) return a;
    return ggt(b, a % b);
}

function lcm(a, b) {
    return (a * b) / ggt(a, b);
}

function gcdRange(n) {
    let res = 1n;
    for (let i = 1n; i <= n; i++) {
        res = lcm(res, i);
    }
    return Number(res);
}

function init(n, k) {
    const pow = new Array(k);
    pow[0] = 1n;
    const nBig = BigInt(n);
    for (let i = 1; i < k; i++) {
        pow[i] = (nBig * pow[i - 1]) % mod;
    }
    return pow;
}

function solve(n, a, x, y, k, M) {
    const pow = init(n, k);
    const gcdR = gcdRange(k - 1);
    const r = new Array(gcdR);
    for (let i = 0; i < gcdR; i++) {
        r[i] = new Array(k + 1).fill(0n);
    }

    const nMinus1 = BigInt(n - 1);
    for (let i = 1; i <= k; i++) {
        const step = k + 1 - i;
        for (let j = 0; j < gcdR; j++) {
            const jump = j - (j % step);
            const term1 = (nMinus1 * r[j][i - 1]) % mod;
            const term2 = (r[jump][i - 1] + BigInt(j) * pow[i - 1]) % mod;
            r[j][i] = (term1 + term2) % mod;
        }
    }

    let sum = 0n;
    const gcdRBig = BigInt(gcdR);
    const kBig = BigInt(k);
    for (let i = 0; i < n; i++) {
        const idx = Number(a % gcdRBig);
        const term1 = r[idx][k];
        const q = a / gcdRBig;
        const term2 = (((q * gcdRBig * kBig) % mod) * pow[k - 1]) % mod;
        sum = (sum + term1 + term2) % mod;
        a = (a * x + y) % M;
    }
    return sum;
}

const fs = require('fs');
const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
if (data.length >= 6) {
    const n = parseInt(data[0], 10);
    const a = BigInt(data[1]);
    const x = BigInt(data[2]);
    const y = BigInt(data[3]);
    const k = parseInt(data[4], 10);
    const M = BigInt(data[5]);
    const ans = solve(n, a, x, y, k, M);
    console.log(ans.toString());
}

