const fs = require('fs');

const mod = 998244353n;

function gcd(a, b) {
    while (b !== 0n) {
        [a, b] = [b, a % b];
    }
    return a;
}

function lcm(a, b) {
    return a / gcd(a, b) * b;
}

function gcdRange(n) {
    let res = 1n;
    for (let i = 1; i <= n; i++) {
        res = lcm(res, BigInt(i));
    }
    return Number(res);
}

function solve() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(BigInt);
    if (input.length === 0) return;

    const n = input[0];
    const a = input[1];
    const x = input[2];
    const y = input[3];
    const k = input[4];
    const M = input[5];

    const kNum = Number(k);
    const nNum = Number(n);

    // init powers
    const pow = new Array(kNum).fill(0n);
    pow[0] = 1n;
    for (let i = 1; i < kNum; i++) {
        pow[i] = (n * pow[i - 1]) % mod;
    }

    const gcdR = gcdRange(kNum - 1);
    const gcdRBig = BigInt(gcdR);

    // Rolling arrays for DP
    let prev = new Array(gcdR).fill(0n);
    let curr = new Array(gcdR).fill(0n);

    const nMinus1 = n - 1n;

    for (let i = 1; i <= kNum; i++) {
        const step = kNum + 1 - i;
        const powVal = pow[i - 1];

        for (let j = 0; j < gcdR; j++) {
            const jump = j - (j % step);
            const term1 = nMinus1 * prev[j];
            const term2 = prev[jump] + BigInt(j) * powVal;
            curr[j] = (term1 + term2) % mod;
        }

        // Swap prev and curr
        [prev, curr] = [curr, prev];
    }

    let sum = 0n;
    let currentA = a;
    const kBig = k;
    const powKMinus1 = pow[kNum - 1];

    for (let i = 0; i < nNum; i++) {
        const idx = Number(currentA % gcdRBig);
        const term1 = prev[idx];

        const div = currentA / gcdRBig;
        const term2 = (((div * gcdRBig * kBig) % mod) * powKMinus1) % mod;

        sum = (sum + term1 + term2) % mod;

        currentA = (currentA * x + y) % M;
    }

    console.log(sum.toString());
}

solve();

